(1, 'STENCH', 'Stench', 'The stench may cause the target to flinch.'),
(2, 'DRIZZLE', 'Drizzle', 'The Pokémon makes it rain if it appears in battle.'),
(3, 'SPEEDBOOST', 'Speed Boost', 'Its Speed stat is gradually boosted.'),
(4, 'BATTLEARMOR', 'Battle Armor', 'The Pokémon is protected against critical hits.'),
(5, 'STURDY', 'Sturdy', 'It cannot be knocked out with one hit.'),
(6, 'DAMP', 'Damp', 'Prevents the use of self-destructing moves.'),
(7, 'LIMBER', 'Limber', 'The Pokémon is protected from paralysis.'),
(8, 'SANDVEIL', 'Sand Veil', 'Boosts the Pokémon''s evasion in a sandstorm.'),
(9, 'STATIC', 'Static', 'Contact with the Pokémon may cause paralysis.'),
(10, 'VOLTABSORB', 'Volt Absorb', 'Restores HP if hit by an Electric-type move.'),
(11, 'WATERABSORB', 'Water Absorb', 'Restores HP if hit by a Water-type move.'),
(12, 'OBLIVIOUS', 'Oblivious', 'Prevents it from becoming infatuated.'),
(13, 'CLOUDNINE', 'Cloud Nine', 'Eliminates the effects of weather.'),
(14, 'COMPOUNDEYES', 'Compound Eyes', 'The Pokémon''s accuracy is boosted.'),
(15, 'INSOMNIA', 'Insomnia', 'Prevents the Pokémon from falling asleep.'),
(16, 'COLORCHANGE', 'Color Change', 'Changes the Pokémon''s type to the foe''s move.'),
(17, 'IMMUNITY', 'Immunity', 'Prevents the Pokémon from getting poisoned.'),
(18, 'FLASHFIRE', 'Flash Fire', 'It powers up Fire-type moves if it''s hit by one.'),
(19, 'SHIELDDUST', 'Shield Dust', 'Blocks the added effects of attacks taken.'),
