(23, 'SHADOWTAG', 'Shadow Tag', 'Prevents the foe from escaping.'),
(24, 'ROUGHSKIN', 'Rough Skin', 'Inflicts damage to the foe on contact.'),
(25, 'WONDERGUARD', 'Wonder Guard', 'Only super-effective moves will hit.'),
(26, 'LEVITATE', 'Levitate', 'Gives full immunity to all Ground-type moves.'),
(27, 'EFFECTSPORE', 'Effect Spore', 'Contact may poison or cause paralysis or sleep.'),
